import SwiftUI

struct MaterialsInventoryView: View {

    @ObservedObject var gamificationViewModel: GamificationViewModel

    // MARK: - View State

    @State private var isLoading = true

    var body: some View {

        List {

            // MARK: - Materials

            Section("Your Materials") {

                if isLoading {

                    ProgressView("Loading materials...")

                } else if gamificationViewModel.materialsInventory.isEmpty {

                    Text("No materials available.")
                        .foregroundColor(.secondary)

                } else {

                    ForEach(gamificationViewModel.materialsInventory) { material in

                        HStack(spacing: 16) {

                            // Material Icon
                            Image(systemName: materialIcon(for: material.code))
                                .font(.title2)
                                .foregroundColor(materialColor(for: material.code))
                                .frame(width: 40)

                            // Material Information
                            VStack(alignment: .leading, spacing: 4) {

                                Text(material.name)
                                    .font(.headline)

                                Text(material.rarity.capitalized)
                                    .font(.caption)
                                    .foregroundColor(.secondary)
                            }

                            Spacer()

                            // Material Quantity
                            Text(material.quantity.formatted())
                                .font(.title3)
                                .fontWeight(.semibold)
                        }
                        .padding(.vertical, 6)
                    }
                }
            }

            // MARK: - Material Information

            Section("About Materials") {

                Text("Crafting Fragments are earned through daily activities.")

                Text("Astral, Nature, and Cyber Crystals come from special rewards such as Rare Crystal Packs.")

                Text("Legendary Cores are earned through special milestones.")
            }
        } // Closes List

    // MARK: - Apply Equipped App Theme

    .scrollContentBackground(.hidden)

    .modifier(
        ProjectHealthThemeModifier(
            gamificationViewModel: gamificationViewModel
        )
    )

    .navigationTitle("Materials Inventory")
    .navigationBarTitleDisplayMode(.inline)


        // Load materials when the screen opens
        .task {

            isLoading = true

            await gamificationViewModel.refreshMaterialsInventory()

            isLoading = false
        }

        // Pull down to refresh
        .refreshable {

            await gamificationViewModel.refreshMaterialsInventory()
        }
    }

    // MARK: - Material Icon

    private func materialIcon(for code: String) -> String {

        switch code {

        case "crafting_fragments":
            return "puzzlepiece.fill"

        case "astral_crystals":
            return "sparkles"

        case "nature_crystals":
            return "leaf.fill"

        case "cyber_crystals":
            return "cpu.fill"

        case "legendary_cores":
            return "diamond.fill"

        default:
            return "circle.fill"
        }
    }

    // MARK: - Material Color

    private func materialColor(for code: String) -> Color {

        switch code {

        case "crafting_fragments":
            return .gray

        case "astral_crystals":
            return .purple

        case "nature_crystals":
            return .green

        case "cyber_crystals":
            return .blue

        case "legendary_cores":
            return .orange

        default:
            return .secondary
        }
    }

} // Closes MaterialsInventoryView
